<?php

namespace Modules\Finance\Services;

use Illuminate\Support\Collection;use Illuminate\Support\Facades\DB;use Modules\MasterData\Models\LineCostRate;use Modules\MasterData\Models\OverheadRate;use Modules\Production\Models\ProductionOrder;use Modules\Production\Services\StandardCostSnapshotService;use RuntimeException;
/** Read-only actual-cost trace. BR-065 removes qty_produced fallback; denominator selection is outside Batch 1. */
class ActualCostingService
{
public function __construct(private StandardCostSnapshotService $snapshots){}
public function computeForMo(ProductionOrder $mo,?string $period=null,?int $companyId=null):array{$companyId??=(int)$mo->company_id;if($companyId!==(int)$mo->company_id)throw new RuntimeException('Production Order bukan milik company aktif.');$period??=$mo->created_at?->format('Y-m')??now()->format('Y-m');if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$period))throw new RuntimeException('Period costing wajib format YYYY-MM.');return DB::transaction(function()use($mo,$period,$companyId):array{$locked=ProductionOrder::withoutGlobalScopes()->with(['routingVersion.operations.operation','style','line','salesOrder'])->where('company_id',$companyId)->whereKey($mo->id)->lockForUpdate()->firstOrFail();$locked=$this->snapshots->forCosting($locked)->fresh(['routingVersion.operations.operation','style','line','salesOrder']);$standard=$locked->standard_cost_snapshot;$material=$this->materialTrace($locked);$production=$this->productionTrace($locked,$period);$subcon=$this->subconTrace($locked);$actual=['material'=>$material['defined_net_flow_cost'],'labor'=>$production['labor']['amount'],'overhead'=>$production['overhead']['amount'],'subcon'=>$subcon['amount'],'other'=>null];$defined=$this->sumWhenDefined(array_values($actual));$std=$this->standardAmounts($standard,$production['output']['qty']);$variance=$this->variance($standard,$std,$actual,false);$gl=DB::table('gl_periods')->where('company_id',$companyId)->where('period',$period)->first();$company=DB::table('companies')->where('id',$companyId)->first();return['mo'=>$locked->doc_no,'production_order'=>['id'=>$locked->id,'doc_no'=>$locked->doc_no,'status'=>$locked->status,'style'=>$locked->style?->only(['id','style_no']),'sales_order'=>$locked->salesOrder?->only(['id','doc_no']),'line'=>$locked->line?->only(['id','code','name']),'qty_planned'=>(float)$locked->qty_planned,'legacy_qty_produced'=>(float)$locked->qty_produced],'period'=>$period,'period_control'=>['gl_status'=>$gl?->status??'NOT_CONFIGURED','behavior'=>'READ_ONLY_COMPUTATION','recalculation'=>'NOT_DEFINED','close_mutation'=>'NOT_APPLICABLE_NO_COST_WRITE'],'currency'=>['code'=>$company?->base_currency,'authority'=>'COMPANY_BASE_CURRENCY','source_transaction_fx'=>'NOT_DEFINED_FOR_ACTUAL_MO_COST'],'output_pcs'=>null,'calculation'=>['mode'=>'COMPUTED_READ_ONLY','persisted'=>false,'status'=>'PARTIAL','actual_cost_document_authority'=>'PRODUCTION_ORDER_COMPUTED_VIEW','actual_costs_table'=>'NOT_IMPLEMENTED','lifecycle'=>'NOT_DEFINED'],'actual'=>['material'=>$actual['material'],'labor'=>null,'machine'=>null,'overhead'=>null,'subcon'=>$actual['subcon'],'other'=>null,'defined_total'=>$defined,'total'=>$defined,'per_pcs'=>null],'components'=>['material'=>$material,'production'=>$production,'subcon'=>$subcon,'other'=>['amount'=>null,'status'=>'NOT_DEFINED','sources'=>[]]],'variance_vs_standard'=>$variance,'standard'=>['snapshot'=>$standard,'amounts_for_output'=>$std,'snapshot_hash'=>$locked->standard_cost_snapshot_hash,'snapshot_source'=>$locked->standard_cost_snapshot_source],'authorities'=>['material_cost'=>$material['authority'],'production_output'=>'BR-065 — EXPLICIT NAMED SOURCE REQUIRED; NOT SELECTED IN BATCH 1','labor'=>'BLOCKED — source selection outside Batch 1','machine_cost'=>'NOT_DEFINED','overhead'=>'BLOCKED — source selection outside Batch 1','subcon'=>'BR-091','wip_valuation'=>'NOT_IMPLEMENTED_IN_BATCH_1','fg_valuation'=>'NOT_IMPLEMENTED_IN_BATCH_1','cost_per_unit_denominator'=>'NOT_IMPLEMENTED_IN_BATCH_1','variance'=>$variance['authority'],'costing_period'=>'RATE_LOOKUP_PERIOD_ONLY','rounding'=>'MONEY DECIMAL(19,4); RATE DECIMAL(18,6)'],'lineage'=>['forward'=>'MO → valued material issue/return + subcon fees; production-output-dependent costing remains blocked','reverse'=>'component → source transaction → MO','wip_fg_bridge'=>'NOT_IMPLEMENTED_IN_BATCH_1']];});}
public function lineageForMo(ProductionOrder $mo,?string $period=null,?int $companyId=null):array{return$this->computeForMo($mo,$period,$companyId);}
private function materialTrace(ProductionOrder $mo):array{$issues=DB::table('stock_ledger as l')->join('material_issues as i',fn($j)=>$j->on('i.id','=','l.source_document_id')->where('l.source_document_type','=','material_issues'))->leftJoin('material_issue_lines as il','il.id','=','l.source_document_line_id')->leftJoin('materials as m','m.id','=','l.material_id')->leftJoin('warehouses as w','w.id','=','l.warehouse_id')->leftJoin('uoms as u','u.id','=','l.uom_id')->leftJoin('fabric_rolls as r','r.id','=','l.roll_id')->where('l.company_id',$mo->company_id)->where('i.company_id',$mo->company_id)->where('i.production_order_id',$mo->id)->where('l.movement_type','MATERIAL_ISSUE')->orderBy('l.id')->select(['l.id as ledger_id','i.id as issue_id','i.doc_no as issue_doc_no','i.mode','il.id as issue_line_id','il.backflush_stage','l.material_id','m.code as material_code','m.name as material_name','l.warehouse_id','w.code as warehouse_code','l.location_id','l.lot_no','l.roll_id','r.roll_no','l.ownership','l.qty_out','l.uom_id','u.code as uom_code','l.unit_cost','l.total_cost','l.created_at'])->get();$returns=DB::table('stock_ledger as l')->join('fabric_returns as fr',fn($j)=>$j->on('fr.id','=','l.source_document_id')->where('l.source_document_type','=','fabric_returns'))->leftJoin('materials as m','m.id','=','l.material_id')->leftJoin('warehouses as w','w.id','=','l.warehouse_id')->leftJoin('uoms as u','u.id','=','l.uom_id')->leftJoin('fabric_rolls as r','r.id','=','l.roll_id')->where('l.company_id',$mo->company_id)->where('fr.company_id',$mo->company_id)->where('fr.production_order_id',$mo->id)->where('l.movement_type','PRODUCTION_RETURN')->orderBy('l.id')->select(['l.id as ledger_id','fr.id as return_id','fr.doc_no as return_doc_no','l.material_id','m.code as material_code','m.name as material_name','l.warehouse_id','w.code as warehouse_code','l.location_id','l.lot_no','l.roll_id','r.roll_no','l.ownership','l.qty_in','l.uom_id','u.code as uom_code','l.unit_cost','l.total_cost','l.created_at'])->get();$ci=$issues->where('ownership','COMPANY')->values();$cr=$returns->where('ownership','COMPANY')->values();$gross=$this->missingValuation($ci)?null:round((float)$ci->sum('total_cost'),4);$ret=$this->missingValuation($cr)?null:round((float)$cr->sum('total_cost'),4);$net=$gross!==null&&$ret!==null?round($gross-$ret,4):null;return['amount'=>$net,'defined_net_flow_cost'=>$net,'gross_issue_cost'=>$gross,'leftover_return_cost'=>$ret,'status'=>$net===null?'PARTIAL':'DEFINED','authority'=>$net===null?'PARTIAL — ledger valuation missing':'BR-005/031/042','wastage_value'=>null,'wastage_authority'=>'NOT_DEFINED_AS_SEPARATE_COST_SOURCE','marker_vs_lay_consumption_authority'=>'BR-031 — LAY_ROLL for new execution; Marker historical only','buyer_owned_excluded_from_valuation'=>true,'issues'=>$issues->map(fn($r)=>(array)$r)->values(),'returns'=>$returns->map(fn($r)=>(array)$r)->values()];}
private function productionTrace(ProductionOrder $mo,string $period):array{$sam=(float)($mo->routingVersion?->total_sam??0);$lineRate=$mo->line_id?LineCostRate::withoutGlobalScopes()->where('company_id',$mo->company_id)->where('line_id',$mo->line_id)->where('period',$period)->first():null;$oh=OverheadRate::withoutGlobalScopes()->where('company_id',$mo->company_id)->where('period',$period)->first();return['status'=>'BLOCKED','output'=>['qty'=>null,'authority'=>'BR-065 — EXPLICIT CONSUMER SOURCE REQUIRED','authoritative'=>false,'legacy_qty_produced_fallback'=>false,'named_source'=>null,'reason'=>'D-09 implementation is outside Batch 1'],'routing'=>['id'=>$mo->routing_version_id,'total_sam'=>$sam>0?$sam:null],'labor'=>['amount'=>null,'formula'=>null,'authority'=>'BLOCKED','line_rate'=>$lineRate?['id'=>$lineRate->id,'line_id'=>$lineRate->line_id,'period'=>$lineRate->period,'cost_per_minute'=>(float)$lineRate->cost_per_minute]:null],'machine'=>['amount'=>null,'authority'=>'NOT_DEFINED','sources'=>[]],'overhead'=>['amount'=>null,'formula'=>null,'authority'=>'BLOCKED','rate'=>$oh?['id'=>$oh->id,'period'=>$oh->period,'rate_per_minute'=>(float)$oh->rate_per_minute]:null,'department_machine_allocation'=>'NOT_DEFINED']];}
private function subconTrace(ProductionOrder $mo):array{$fees=DB::table('subcon_fees as f')->join('subcon_orders as j','j.id','=','f.subcon_order_id')->join('suppliers as s','s.id','=','j.supplier_id')->leftJoin('subcon_order_lines as jl','jl.id','=','f.subcon_order_line_id')->leftJoin('operations as o','o.id','=','j.operation_id')->where('j.company_id',$mo->company_id)->where('j.production_order_id',$mo->id)->orderBy('f.id')->select(['f.id as fee_id','f.subcon_order_line_id','f.receipt_reference','f.return_date','f.qty_returned','f.fee_per_pcs','f.total_fee','j.id as job_work_id','j.doc_no as job_work_doc_no','j.status as job_work_status','j.operation_id','o.code as operation_code','o.name as operation_name','s.id as supplier_id','s.code as supplier_code','s.name as supplier_name'])->get();return['amount'=>round((float)$fees->sum('total_fee'),4),'status'=>'DEFINED','authority'=>'BR-091','fees'=>$fees->map(fn($r)=>(array)$r)->values(),'vendor_invoice_ap_match'=>'NOT_IMPLEMENTED'];}
private function missingValuation(Collection $rows):bool{return$rows->contains(fn($r)=>$r->unit_cost===null||$r->total_cost===null);}private function sumWhenDefined(array $a):?float{return collect($a)->contains(fn($v)=>$v===null)?null:round(array_sum($a),4);}private function standardAmounts(array $s,?float $output):?array{return$output===null?null:['material'=>round(((float)$s['fabric']+(float)$s['trim'])*$output,4),'labor'=>round((float)$s['labor']*$output,4),'overhead'=>round((float)$s['overhead']*$output,4),'subcon'=>round((float)$s['subcon']*$output,4),'other'=>round((float)$s['other']*$output,4)];}private function variance(array $s,?array $std,array $actual,bool $authoritative):array{$v=[];foreach(['material','labor','overhead','subcon','other']as$c)$v[$c]=$std!==null&&$actual[$c]!==null?round($actual[$c]-$std[$c],4):null;return array_merge($v,['total'=>null,'standard_total'=>null,'cost_sheet'=>$s['doc_no'],'cost_sheet_id'=>$s['cost_sheet_id'],'snapshot_hash'=>null,'authority'=>'PARTIAL — explicit costing denominator/source is outside Batch 1','status'=>'PARTIAL']);}
}
